def solve_peak_calls(text):
    tokens = text.split()
    n, k = int(tokens[0]), int(tokens[1])
    events = []
    for i in range(n):
        start, end = int(tokens[2 + 2 * i]), int(tokens[3 + 2 * i])
        events.append((start, 1))
        events.append((end, -1))
    events.sort()
    live = best = 0
    begin = None
    i = 0
    while i < len(events):
        time = events[i][0]
        while i < len(events) and events[i][0] == time:
            live += events[i][1]
            i += 1
        if live >= k and begin is None:
            begin = time
        elif live < k and begin is not None:
            best = max(best, time - begin)
            begin = None
    return str(best)

